import { FFmpeg } from '@ffmpeg/ffmpeg';

let ffmpeg = null;
let isLoading = false;
let loadError = null;

/**
 * 初始化 ffmpeg 实例（懒加载，单线程 core，无需 SharedArrayBuffer）
 * @returns {Promise<boolean>} 是否成功
 */
export async function initFFmpeg() {
    if (ffmpeg && ffmpeg.loaded) return true;
    if (loadError) return false;
    if (isLoading) {
        // 等待已有加载完成
        while (isLoading) {
            await new Promise(resolve => setTimeout(resolve, 100));
        }
        return ffmpeg !== null && ffmpeg.loaded;
    }

    isLoading = true;
    loadError = null;

    try {
        const baseURL = `${window.location.origin}/ffmpeg`;
        ffmpeg = new FFmpeg();
        await ffmpeg.load({
            // 不传 classWorkerURL：交给打包器产出 worker（webpack 会把传参那条分支
            // 改写成无效的 require 存根，运行时直接抛 "Cannot find module"）。
            // worker 因此是 classic worker，core 必须用 UMD 版本走 importScripts。
            coreURL: `${baseURL}/ffmpeg-core.js`,
            // wasm 原始体积 32MB 超过 Cloudflare Pages 单文件 25MB 限制，
            // 部署的是 gzip 压缩版（约 10MB），在浏览器端解压后通过 Blob URL 加载
            wasmURL: await getWasmBlobURL(baseURL),
        });
        isLoading = false;
        return true;
    } catch (error) {
        console.error('FFmpeg load failed:', error);
        loadError = error;
        isLoading = false;
        ffmpeg = null;
        return false;
    }
}

/**
 * 拉取 gzip 压缩的 wasm 并在浏览器端解压，返回 Blob URL
 * （规避 CF Pages 25MB 单文件限制）
 */
async function getWasmBlobURL(baseURL) {
    if (typeof DecompressionStream === 'undefined') {
        throw new Error('DecompressionStream is not supported in this browser');
    }
    const res = await fetch(`${baseURL}/ffmpeg-core.wasm.gz`);
    if (!res.ok) {
        throw new Error(`Failed to fetch ffmpeg-core.wasm.gz: ${res.status}`);
    }
    const decompressed = new Response(res.body.pipeThrough(new DecompressionStream('gzip')));
    const buf = await decompressed.arrayBuffer();
    return URL.createObjectURL(new Blob([buf], { type: 'application/wasm' }));
}

/**
 * 确保 ffmpeg 已加载
 */
async function ensureFFmpegLoaded() {
    if (!ffmpeg || !ffmpeg.loaded) {
        const success = await initFFmpeg();
        if (!success) {
            throw new Error('FFmpeg initialization failed');
        }
    }
    return ffmpeg;
}

/**
 * 检测视频编码
 * @param {File} file - 视频文件
 * @returns {Promise<{codec: string, duration: number, hasAudio: boolean}>}
 */
async function probeVideo(file) {
    const ff = await ensureFFmpegLoaded();
    const tempName = `temp_${Date.now()}.${getFileExtension(file.name)}`;

    await ff.writeFile(tempName, new Uint8Array(await file.arrayBuffer()));

    // ffmpeg -i <file> 的流信息输出在 stderr，通过 log 事件捕获
    let info = '';
    const logHandler = ({ message }) => {
        info += (message || '') + '\n';
    };
    ff.on('log', logHandler);
    try {
        // 不带输出文件会以退出码 1 结束，属预期，exec 不会抛异常
        await ff.exec(['-i', tempName]);
    } catch (e) {
        // 忽略错误，只收集信息
    } finally {
        ff.off('log', logHandler);
    }

    // 解析视频编码信息
    const videoMatch = info.match(/Stream #\d+:\d+.*Video: (\w+)/i);
    const audioMatch = info.match(/Stream #\d+:\d+.*Audio: (\w+)/i);
    const durationMatch = info.match(/Duration: (\d+):(\d+):([\d.]+)/);

    const codec = videoMatch ? videoMatch[1].toLowerCase() : 'unknown';
    const audioCodec = audioMatch ? audioMatch[1].toLowerCase() : null;
    const duration = durationMatch
        ? parseInt(durationMatch[1]) * 3600 + parseInt(durationMatch[2]) * 60 + parseFloat(durationMatch[3])
        : 0;

    // 清理临时文件
    try {
        await ff.deleteFile(tempName);
    } catch (e) {
        // 忽略删除错误
    }

    return {
        codec,
        audioCodec,
        duration,
        hasAudio: audioMatch !== null,
        hasVideo: videoMatch !== null,
    };
}

/**
 * 转码视频为 H.264
 * @param {File} file - 原始视频文件
 * @param {Object} options - 转码选项
 * @returns {Promise<File>} 转码后的视频文件
 */
export async function transcodeToH264(file, options = {}) {
    const {
        preset = 'veryfast',
        crf = 23,
        audioBitrate = 128,
        maxHeight = 0,
        maxSizeMB = 200,
        timeoutSec = 0,
        onProgress = null,
    } = options;

    // 检查文件大小
    const fileSizeMB = file.size / (1024 * 1024);
    if (maxSizeMB > 0 && fileSizeMB > maxSizeMB) {
        throw new Error(`File too large: ${fileSizeMB.toFixed(2)}MB > ${maxSizeMB}MB`);
    }

    const ff = await ensureFFmpegLoaded();

    const inputName = `input_${Date.now()}.${getFileExtension(file.name)}`;
    const outputName = `output_${Date.now()}.mp4`;

    let progressHandler = null;
    try {
        // 写入输入文件
        await ff.writeFile(inputName, new Uint8Array(await file.arrayBuffer()));

        // 设置进度回调
        if (onProgress) {
            progressHandler = ({ progress }) => {
                const ratio = typeof progress === 'number' ? progress : 0;
                onProgress(Math.min(Math.max(ratio, 0), 1));
            };
            ff.on('progress', progressHandler);
        }

        // 可选：限制输出高度（仅在超过上限时缩小，不放大），保持宽高比且宽高均为偶数
        // 公式：宽度自动(-2)，高度取 min(上限, 原始高度)；逗号在滤镜串中需转义
        const scaleArgs = maxHeight > 0
            ? ['-vf', `scale=-2:min(${maxHeight}\\,ih)`]
            : [];

        // 构建 ffmpeg 命令
        const args = [
            '-i', inputName,
            '-map', '0:v:0',  // 只取第一个视频流
            '-map', '0:a?',   // 音频流可选
            ...scaleArgs,
            '-c:v', 'libx264',
            '-preset', preset,
            '-crf', crf.toString(),
            '-pix_fmt', 'yuv420p',
            '-profile:v', 'high',
            '-c:a', 'aac',
            '-b:a', `${audioBitrate}k`,
            '-movflags', '+faststart',
            '-y',
            outputName
        ];

        // 执行转码，ret === 0 表示成功
        const timeoutMs = timeoutSec > 0 ? timeoutSec * 1000 : -1;
        const ret = await ff.exec(args, timeoutMs);
        if (ret !== 0) {
            throw new Error(`ffmpeg exited with code ${ret}`);
        }

        // 读取输出文件
        const data = await ff.readFile(outputName);

        // 清理临时文件
        try {
            await ff.deleteFile(inputName);
            await ff.deleteFile(outputName);
        } catch (e) {
            // 忽略删除错误
        }

        // 创建新的 File 对象
        const newFileName = file.name.replace(/\.[^.]+$/, '.mp4');
        const transcodedFile = new File([data], newFileName, { type: 'video/mp4' });

        return transcodedFile;
    } catch (error) {
        // 清理临时文件
        try {
            await ff.deleteFile(inputName);
            await ff.deleteFile(outputName);
        } catch (e) {
            // 忽略删除错误
        }
        throw error;
    } finally {
        if (progressHandler) {
            ff.off('progress', progressHandler);
        }
    }
}

/**
 * 检查是否需要转码，并返回探测到的原始编码
 * @param {File} file - 视频文件
 * @param {Object} config - 配置
 * @returns {Promise<{needed: boolean, codec: string|null}>} codec 仅在需要探测时才有值
 */
export async function checkTranscodeNeed(file, config) {
    if (!config.enabled) return { needed: false, codec: null };
    if (!file.type.startsWith('video/')) return { needed: false, codec: null };

    const fileSizeMB = file.size / (1024 * 1024);
    if (config.maxSizeMB > 0 && fileSizeMB > config.maxSizeMB) return { needed: false, codec: null };

    // 如果不启用自动检测，则对所有视频转码
    if (!config.autoDetect) return { needed: true, codec: null };

    // 自动检测：只有非 H.264 视频才转码
    const probe = await probeVideo(file);
    if (!probe.hasVideo) return { needed: false, codec: probe.codec };

    // 已经是 H.264，不需要转码
    if (probe.codec === 'h264') return { needed: false, codec: probe.codec };

    // 常见的非 H.264 编码
    const nonH264Codecs = ['hevc', 'h265', 'av1', 'vp9', 'vp8', 'mpeg4', 'msmpeg4'];
    return { needed: nonH264Codecs.includes(probe.codec), codec: probe.codec };
}

/**
 * 获取文件扩展名
 */
function getFileExtension(filename) {
    const match = filename.match(/\.([^.]+)$/);
    return match ? match[1] : 'mp4';
}
